  return (
    <IconContainer
      className={clsx(IconClassName, className)}
      color={color}
      size={iconSizes[size]}
      {...rest}
    >
      {name ? (
        <IconProvider color={color} iconName={name} size={iconSizes[size]} />
      ) : null}
    </IconContainer>
  );
}

Icon.displayName = "Icon";

export { Icon };

